{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a close analogue sharing the methoxybenzamide and piperidine/amine framework, has an absolute oral bioavailability of 32 ± 7% in normal subjects, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ketanserin, which shares the piperidine and fluorophenyl motifs, has an absolute oral bioavailability of 55.5% in healthy subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Safinamide, containing an aryl ether, amine, amide, and fluorophenyl group similar to the query, has an absolute oral bioavailability of 95% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Haloperidol, with a piperidine and chlorophenyl/fluorophenyl arrangement, has an absolute oral bioavailability of 35% in patients, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Vernakalant, sharing piperidine, methoxyphenyl, and ether features, has an absolute oral bioavailability of 58 ± 19% in fasted healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Brigatinib, which contains methoxy, amino, and piperidine/piperazine-like features, has an oral bioavailability of 46% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Gilteritinib, with methoxy, amino, and saturated nitrogen heterocycles, has an estimated oral bioavailability greater than 61.2%, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues report absolute oral bioavailability values at or above 20%, mostly in the 30-95% range, with no affirmative evidence of F < 20%; therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement is available for the query molecule itself.",
    "Some supporting records are not explicitly labeled as absolute bioavailability, but the absolute records among close analogues are consistently >=20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

